function formatArticleCount(count, lang = "zh") {
  if (!count || count <= 0) return "";
  if (lang === "zh") {
    if (count >= 1e4) {
      const w = parseFloat((count / 1e4).toFixed(0));
      return `${w}\u4E07\u8BCD\u6761`;
    }
    return `${count}\u8BCD\u6761`;
  } else {
    if (count >= 1e6) {
      const m = parseFloat((count / 1e6).toFixed(2));
      return `${m}M articles`;
    }
    if (count >= 1e3) {
      const k = Math.round(count / 1e3);
      return `${k}K articles`;
    }
    return `${count} ${count === 1 ? "article" : "articles"}`;
  }
}

